export {
  createDataTableQueryOptions,
  getMetaPage,
  type DataTableQueryOptionsConfig,
  type InfiniteQueryMeta,
  type InfiniteQueryResponse,
} from "./create-query-options";
export {
  formatConformanceReport,
  runEndpointConformance,
  type ConformanceCheck,
  type ConformanceManifest,
  type ConformanceReport,
  type EndpointConformanceOptions,
} from "./conformance";
export {
  ENCODING_CONSTRAINTS,
  FILTER_ENCODING,
  REQUEST_PARAMS,
  isContractValid,
  validateListResponse,
  type ContractIssue,
  type ValidateResponseOptions,
} from "./contract";
export {
  applyFacets,
  getFacetedMinMaxValues,
  getFacetedUniqueValues,
} from "./faceted";
export {
  coerceRowTimestamps,
  DataTableFetchError,
  defaultBaseUrl,
  jsonParser,
  offsetPagination,
  opaqueCursorPagination,
  resolveUrl,
  schemaJsonParser,
  superjsonParser,
  timestampCursorPagination,
  timestampKeys,
  transportFetch,
  type PaginationStrategy,
  type ResponseParser,
  type TimestampCursorPageParam,
  type TimestampKeySource,
  type Transport,
} from "./transport";
export {
  facetMetadataSchema,
  type BaseChartSchema,
  type FacetMetadataSchema,
} from "./types";

import type { ActionDescriptor } from "@/lib/actions/types";
import { infiniteQueryOptions, keepPreviousData } from "@tanstack/react-query";
import type { PaginationStrategy, Transport } from "./transport";
import {
  resolveUrl,
  timestampCursorPagination,
  transportFetch,
} from "./transport";
import type { BaseChartSchema, FacetMetadataSchema } from "./types";

export type InfiniteQueryMeta<TMeta = Record<string, unknown>> = {
  totalRowCount: number;
  filterRowCount: number;
  chartData: BaseChartSchema[];
  facets: Record<string, FacetMetadataSchema>;
  /**
   * What can be done to these rows. Rendered as-is by the `data-table-actions`
   * block; the server owns the list (see `createActionHandler`).
   */
  actions?: ActionDescriptor[];
  metadata?: TMeta;
};

export type InfiniteQueryResponse<TData, TMeta = unknown> = {
  data: TData;
  meta: InfiniteQueryMeta<TMeta>;
  prevCursor: number | null;
  nextCursor: number | null;
};

/**
 * Search keys that address a single row or a view mode rather than a filter.
 * They are cleared from both the request and the cache key so that opening a
 * row's sheet does not refetch the list under a new key.
 */
const DEFAULT_OMIT_KEYS = ["uuid", "live"] as const;

/**
 * What React Query carries between pages.
 *
 * The pagination strategy owns `page` and nothing else looks inside it — it may
 * be an object, a number, or an opaque token. `_meta` sits *outside* it because
 * meta skipping is a transport-level concern, not a pagination one: the same
 * flag has to work whether pages are addressed by cursor, opaque token, or
 * offset.
 */
// `any` for the same reason as `pagination` below: the strategy owns this type
// and nothing here can name it without leaking a generic through every call site.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
type MetaPageParam = { page: any; _meta: boolean };

export type DataTableQueryOptionsConfig<TData, TMeta> = {
  queryKeyPrefix: string;
  apiEndpoint: string;
  searchParamsSerializer: (search: Record<string, unknown>) => string;
  /**
   * Append `_meta=false` to pagination requests so the API can skip recomputing
   * chart data and facets that the client already holds from the initial page.
   *
   * Opt-in, and only safe when both halves are in place:
   * 1. the route honors `_meta=false` (and still returns per-row fields — only
   *    `meta` is skippable), and
   * 2. the client reads `meta` via `getMetaPage`, not from the last page.
   *
   * @default false
   */
  skipMetaOnPagination?: boolean;
  /**
   * How to reach the endpoint: base URL, headers, credentials, and how to parse
   * the body. Omitted, it stays what it always was — same-origin `fetch` and a
   * SuperJSON payload.
   */
  transport?: Transport<TData, TMeta>;
  /**
   * How pages are addressed. Defaults to a bidirectional cursor over a
   * timestamp column, which is what a log table wants; see
   * `offsetPagination` and `opaqueCursorPagination` for endpoints that page
   * some other way.
   */
  // `any` on the page param is deliberate: the param type is existential — the
  // strategy owns it and nothing else in this config refers to it, so surfacing
  // it as a third generic would force every call site that names `TData` and
  // `TMeta` to name it too, just to keep the default.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  pagination?: PaginationStrategy<any>;
  /** Extra search keys to clear from the request and the cache key. */
  omitKeys?: readonly string[];
  /** Overrides merged into the generated `infiniteQueryOptions`. */
  queryOptions?: {
    staleTime?: number;
    gcTime?: number;
    refetchOnWindowFocus?: boolean;
    retry?: number | boolean;
  };
};

/**
 * Factory for creating infinite query options for data tables.
 *
 * Parametrizes the query key prefix, endpoint, serializer, transport, and
 * pagination — everything else (caching, the stable key, page-param plumbing)
 * is shared.
 */
export function createDataTableQueryOptions<TData, TMeta>(
  config: DataTableQueryOptionsConfig<TData, TMeta>,
) {
  const pagination = config.pagination ?? timestampCursorPagination();
  // Both the request and the cache key drop these. Kept as a plain object so
  // spreading it cannot be reordered into a no-op by a later key.
  const cleared: Record<string, null> = {};
  for (const key of [...DEFAULT_OMIT_KEYS, ...(config.omitKeys ?? [])]) {
    cleared[key] = null;
  }

  return (search: Record<string, unknown>) => {
    const initialPageParam: MetaPageParam = {
      page: pagination.getInitialPageParam(search),
      _meta: true,
    };

    // Normalize empty arrays to null for consistent serialization
    const normalized: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(search)) {
      if (Array.isArray(value) && value.length === 0) {
        normalized[key] = null;
      } else {
        normalized[key] = value;
      }
    }

    const stableKey = config.searchParamsSerializer({
      ...normalized,
      ...cleared,
      // The page param is not part of the identity of the list — every page of
      // one filter state belongs under one key.
      ...Object.fromEntries(pagination.pageParamKeys.map((key) => [key, null])),
    });

    return infiniteQueryOptions({
      queryKey: [config.queryKeyPrefix, stableKey],
      queryFn: async ({ pageParam, signal }) => {
        const serialize = config.searchParamsSerializer({
          ...pagination.applyPageParam(search, pageParam.page),
          ...cleared,
        });

        // Appended after serialization on purpose: `_meta` is a transport-level
        // control param, not part of any consumer's search-param schema. Routing
        // it through the serializer would either pollute every consumer's parser
        // contract or be silently dropped by an allow-list serializer.
        const url = resolveUrl(
          config.transport,
          `${config.apiEndpoint}${serialize}`,
        );
        const skipMeta = config.skipMetaOnPagination && !pageParam._meta;

        return transportFetch<TData, TMeta>(
          skipMeta ? `${url}${url.includes("?") ? "&" : "?"}_meta=false` : url,
          config.transport,
          { signal },
        );
      },
      initialPageParam,
      getPreviousPageParam: (firstPage, _allPages, firstPageParam) => {
        const page = pagination.getPreviousPageParam(
          firstPage,
          firstPageParam.page,
        );
        return page === null ? null : { page, _meta: false };
      },
      getNextPageParam: (lastPage, _allPages, lastPageParam) => {
        const page = pagination.getNextPageParam(lastPage, lastPageParam.page);
        return page === null ? null : { page, _meta: false };
      },
      refetchOnWindowFocus: config.queryOptions?.refetchOnWindowFocus ?? false,
      placeholderData: keepPreviousData,
      staleTime: config.queryOptions?.staleTime ?? 1000 * 60 * 5,
      ...(config.queryOptions?.gcTime !== undefined
        ? { gcTime: config.queryOptions.gcTime }
        : {}),
      ...(config.queryOptions?.retry !== undefined
        ? { retry: config.queryOptions.retry }
        : {}),
    });
  };
}

/**
 * The page whose `meta` is populated.
 *
 * With `skipMetaOnPagination`, only the page fetched with `_meta: true` carries
 * chart data, facets and metadata — and it is not always index 0, because
 * `fetchPreviousPage` (live mode) prepends pages. React Query keeps `pageParams`
 * aligned with `pages`, so the flag on the page param identifies it exactly.
 * Inferring it from the payload instead (e.g. "the page whose chartData is
 * non-empty") misfires whenever a filter legitimately matches nothing.
 *
 * Falls back to the last page, which is the correct answer when meta skipping is
 * off and every page carries the same meta.
 */
export function getMetaPage<TData, TMeta>(
  data:
    | { pages: InfiniteQueryResponse<TData, TMeta>[]; pageParams: unknown[] }
    | undefined,
): InfiniteQueryResponse<TData, TMeta> | undefined {
  if (!data?.pages?.length) return undefined;
  const index = data.pageParams.findIndex(
    (param) => (param as { _meta?: boolean } | null)?._meta,
  );
  return data.pages[index] ?? data.pages[data.pages.length - 1];
}

import SuperJSON from "superjson";
import type { InfiniteQueryResponse } from "./create-query-options";

/**
 * The transport layer: everything about *how* the table talks to an endpoint,
 * separated from *what* it asks for.
 *
 * The table used to hard-code all of this — same-origin `fetch`, no headers, no
 * `response.ok` check, SuperJSON, and a numeric-timestamp cursor. That works for
 * an endpoint we own and nothing else, which is why the schema builder had to
 * write its own offset-based query options rather than reuse the block. A
 * headless table pointed at someone else's API needs each of those four to be a
 * choice.
 */

// ── Errors ──────────────────────────────────────────────────────────────────

/**
 * A non-2xx response, or a body that could not be parsed.
 *
 * Thrown instead of letting a 500's HTML reach `SuperJSON.parse` and surface as
 * an opaque syntax error. React Query surfaces this as the query's `error`, so
 * the status and URL are the two things a caller needs to render something
 * useful.
 */
export class DataTableFetchError extends Error {
  readonly status: number;
  readonly url: string;
  /** First 500 chars of the response body, when one was readable. */
  readonly body?: string;

  constructor(args: {
    message: string;
    status: number;
    url: string;
    body?: string;
    cause?: unknown;
  }) {
    super(args.message, { cause: args.cause });
    this.name = "DataTableFetchError";
    this.status = args.status;
    this.url = args.url;
    this.body = args.body;
  }
}

// ── Response parsing ────────────────────────────────────────────────────────

export type ResponseParser<TData, TMeta> = (
  response: Response,
) => Promise<InfiniteQueryResponse<TData, TMeta>>;

/** Reads at most `limit` chars of a body for an error message, never throwing. */
async function readBodySnippet(
  response: Response,
  limit = 500,
): Promise<string | undefined> {
  try {
    const text = await response.text();
    return text.slice(0, limit);
  } catch {
    return undefined;
  }
}

/**
 * The historical default: the server `SuperJSON.stringify`s its payload, so
 * `Date`s survive the wire without the client knowing which columns hold them.
 */
export function superjsonParser<TData, TMeta>(): ResponseParser<TData, TMeta> {
  return async (response) => {
    const json = await response.json();
    return SuperJSON.parse<InfiniteQueryResponse<TData, TMeta>>(json);
  };
}

/**
 * Plain JSON, taken exactly as the endpoint sent it.
 *
 * Timestamps arrive as whatever the endpoint serialized them to — usually ISO
 * strings. Use {@link schemaJsonParser} when the schema is available and those
 * should become `Date`s.
 */
export function jsonParser<TData, TMeta>(): ResponseParser<TData, TMeta> {
  return async (response) =>
    (await response.json()) as InfiniteQueryResponse<TData, TMeta>;
}

/** The subset of a `SchemaJSON` this module needs: which keys hold timestamps. */
export type TimestampKeySource = {
  columns: readonly { key: string; kind?: string }[];
};

/**
 * Collect the keys of every `timestamp` column, including nested ones written
 * with the `"timing.dns"` dotted convention.
 */
export function timestampKeys(schema: TimestampKeySource): string[] {
  return schema.columns
    .filter((column) => column.kind === "timestamp")
    .map((column) => column.key);
}

/** Reads a possibly-dotted key path off a row. */
function getPath(row: Record<string, unknown>, path: string): unknown {
  if (!path.includes(".")) return row[path];
  let current: unknown = row;
  for (const segment of path.split(".")) {
    if (current === null || typeof current !== "object") return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

/** Writes a possibly-dotted key path on a row, creating objects as needed. */
function setPath(
  row: Record<string, unknown>,
  path: string,
  value: unknown,
): void {
  if (!path.includes(".")) {
    row[path] = value;
    return;
  }
  const segments = path.split(".");
  const last = segments.pop()!;
  let current: Record<string, unknown> = row;
  for (const segment of segments) {
    const next = current[segment];
    if (next === null || typeof next !== "object") return;
    current = next as Record<string, unknown>;
  }
  current[last] = value;
}

/**
 * Coerce one row's timestamp columns to `Date`.
 *
 * Anything already a `Date` is left alone, and anything that does not parse is
 * left alone too — a column the endpoint sent as `null`, `""`, or a string we
 * do not understand stays as it was rather than becoming an `Invalid Date` that
 * renders as "Invalid Date" three layers down.
 */
export function coerceRowTimestamps<TRow>(row: TRow, keys: string[]): TRow {
  if (row === null || typeof row !== "object") return row;
  const record = row as Record<string, unknown>;
  for (const key of keys) {
    const value = getPath(record, key);
    if (value instanceof Date) continue;
    if (typeof value !== "string" && typeof value !== "number") continue;
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) continue;
    setPath(record, key, date);
  }
  return row;
}

/**
 * Plain JSON, with timestamp columns revived to `Date` using the schema.
 *
 * This is what makes a third-party endpoint work without asking it to adopt
 * SuperJSON: we already know from the schema which columns are timestamps, so
 * ISO strings can be revived on the way in.
 */
export function schemaJsonParser<TData, TMeta>(
  schema: TimestampKeySource,
): ResponseParser<TData, TMeta> {
  const keys = timestampKeys(schema);
  return async (response) => {
    const payload = (await response.json()) as InfiniteQueryResponse<
      TData,
      TMeta
    >;
    if (keys.length === 0) return payload;
    if (Array.isArray(payload.data)) {
      for (const row of payload.data) coerceRowTimestamps(row, keys);
    }
    return payload;
  };
}

// ── Transport ───────────────────────────────────────────────────────────────

export type Transport<TData = unknown, TMeta = unknown> = {
  /**
   * Prefix for the endpoint path. A string, or a function called per request
   * for the cases where it is only known at call time.
   *
   * Defaults to {@link defaultBaseUrl}: same-origin in the browser, `VERCEL_URL`
   * or localhost on the server. Point it at another origin to talk to an API
   * that is not the app — that endpoint then needs CORS.
   */
  baseUrl?: string | (() => string);
  /**
   * Per-request headers. A function so an auth token can be read fresh on every
   * request rather than captured once at module scope, and async so it can wait
   * on a token refresh.
   */
  headers?: HeadersInit | (() => HeadersInit | Promise<HeadersInit>);
  /** Passed through to `fetch` — `"include"` for cookie-authenticated APIs. */
  credentials?: RequestCredentials;
  /** Swappable `fetch`, for tests and for runtimes that wrap it. */
  fetch?: typeof fetch;
  /** How to turn a `Response` into the payload. Defaults to {@link superjsonParser}. */
  parseResponse?: ResponseParser<TData, TMeta>;
};

/** Same-origin in the browser; `VERCEL_URL` or localhost on the server. */
export function defaultBaseUrl(): string {
  if (typeof window !== "undefined") return "";
  if (process.env.VERCEL_URL) return `https://${process.env.VERCEL_URL}`;
  return `http://localhost:${process.env.PORT ?? 3000}`;
}

/** Only the base URL matters here, so the parameter is narrowed to it. */
type BaseUrlSource = { baseUrl?: string | (() => string) };

function resolveBaseUrl(transport: BaseUrlSource | undefined) {
  const baseUrl = transport?.baseUrl;
  if (baseUrl === undefined) return defaultBaseUrl();
  return typeof baseUrl === "function" ? baseUrl() : baseUrl;
}

/**
 * Perform one request and parse it, raising {@link DataTableFetchError} on a
 * non-2xx status or an unparseable body.
 */
export async function transportFetch<TData, TMeta>(
  url: string,
  transport: Transport<TData, TMeta> | undefined,
  init?: { signal?: AbortSignal },
): Promise<InfiniteQueryResponse<TData, TMeta>> {
  const doFetch = transport?.fetch ?? fetch;
  const headers =
    typeof transport?.headers === "function"
      ? await transport.headers()
      : transport?.headers;

  const response = await doFetch(url, {
    headers,
    credentials: transport?.credentials,
    signal: init?.signal,
  });

  if (!response.ok) {
    throw new DataTableFetchError({
      message:
        `Request to ${url} failed with ${response.status} ${response.statusText}`.trim(),
      status: response.status,
      url,
      body: await readBodySnippet(response),
    });
  }

  const parse = transport?.parseResponse ?? superjsonParser<TData, TMeta>();
  try {
    return await parse(response);
  } catch (cause) {
    throw new DataTableFetchError({
      message: `Could not parse the response from ${url}`,
      status: response.status,
      url,
      cause,
    });
  }
}

/** Joins a base URL and a path without doubling or dropping the separator. */
export function resolveUrl(
  transport: BaseUrlSource | undefined,
  path: string,
): string {
  const base = resolveBaseUrl(transport);
  if (!base) return path;
  return `${base.replace(/\/$/, "")}${path.startsWith("/") ? "" : "/"}${path}`;
}

// ── Pagination ──────────────────────────────────────────────────────────────

/**
 * How pages are addressed.
 *
 * The table used to assume one answer — a numeric millisecond timestamp read
 * from a `date` column, defaulting to `Date.now()`. That is a good default for
 * an append-only log and wrong for everything else, so it is now one strategy
 * among several.
 *
 * `TPageParam` is whatever React Query carries between pages. It is written into
 * the search object by `applyPageParam` before serialization, so a strategy
 * fully owns its wire representation.
 */
export type PaginationStrategy<TPageParam = unknown> = {
  /** Page param for the first request, derived from the current filter state. */
  getInitialPageParam: (search: Record<string, unknown>) => TPageParam;
  /** `null` ends the list. */
  getNextPageParam: (
    lastPage: InfiniteQueryResponse<unknown, unknown>,
    lastPageParam: TPageParam,
  ) => TPageParam | null;
  /** `null` means "no backwards paging" — live mode stays off. */
  getPreviousPageParam: (
    firstPage: InfiniteQueryResponse<unknown, unknown>,
    firstPageParam: TPageParam,
  ) => TPageParam | null;
  /** Merge the page param into the search object sent to the serializer. */
  applyPageParam: (
    search: Record<string, unknown>,
    pageParam: TPageParam,
  ) => Record<string, unknown>;
  /**
   * Search keys this strategy owns. Cleared when building the cache key, so two
   * pages of the same filter state share one query key.
   */
  readonly pageParamKeys: readonly string[];
};

export type TimestampCursorPageParam = {
  cursor: number;
  direction: "next" | "prev";
};

/**
 * Cursor over a timestamp column, paging in both directions. The historical
 * default, unchanged: the cursor is epoch milliseconds, the first page starts
 * at `search.cursor` or now, and `direction` tells the server which way to read.
 */
export function timestampCursorPagination(options?: {
  cursorKey?: string;
  directionKey?: string;
}): PaginationStrategy<TimestampCursorPageParam> {
  const cursorKey = options?.cursorKey ?? "cursor";
  const directionKey = options?.directionKey ?? "direction";
  return {
    pageParamKeys: [cursorKey, directionKey],
    getInitialPageParam: (search) => {
      const cursor = search[cursorKey] as Date | undefined;
      return {
        cursor: cursor?.getTime?.() ?? Date.now(),
        direction: "next",
      };
    },
    getNextPageParam: (lastPage) =>
      lastPage.nextCursor
        ? { cursor: Number(lastPage.nextCursor), direction: "next" }
        : null,
    getPreviousPageParam: (firstPage) =>
      firstPage.prevCursor
        ? { cursor: Number(firstPage.prevCursor), direction: "prev" }
        : null,
    applyPageParam: (search, pageParam) => ({
      ...search,
      [cursorKey]: new Date(pageParam.cursor),
      [directionKey]: pageParam.direction,
    }),
  };
}

/**
 * An opaque cursor the client never interprets — the server's `nextCursor` is
 * echoed back verbatim. Forward-only, because an opaque token carries no
 * ordering the client could reverse.
 */
export function opaqueCursorPagination(options?: {
  cursorKey?: string;
}): PaginationStrategy<string | number | null> {
  const cursorKey = options?.cursorKey ?? "cursor";
  return {
    pageParamKeys: [cursorKey],
    getInitialPageParam: (search) =>
      (search[cursorKey] as string | number | null | undefined) ?? null,
    getNextPageParam: (lastPage) => lastPage.nextCursor ?? null,
    getPreviousPageParam: () => null,
    applyPageParam: (search, pageParam) => ({
      ...search,
      [cursorKey]: pageParam,
    }),
  };
}

/**
 * Offset/limit paging, for endpoints with no cursor at all.
 *
 * `nextCursor` is honoured as the next offset when the server sends one;
 * otherwise the offset advances by `size` until a page comes back short, which
 * is the only end-of-list signal a bare offset API gives.
 */
export function offsetPagination(options: {
  size: number;
  offsetKey?: string;
  sizeKey?: string;
}): PaginationStrategy<number> {
  const offsetKey = options.offsetKey ?? "offset";
  const sizeKey = options.sizeKey ?? "size";
  const size = options.size;
  return {
    pageParamKeys: [offsetKey],
    getInitialPageParam: (search) => Number(search[offsetKey] ?? 0),
    getNextPageParam: (lastPage, lastPageParam) => {
      if (lastPage.nextCursor !== null && lastPage.nextCursor !== undefined) {
        return Number(lastPage.nextCursor);
      }
      // No cursor from the server: infer from what arrived. A short page is the
      // last page; a full one might not be, so ask for the next window. The
      // offset has to accumulate across pages, which is why the strategy is
      // handed the page param that produced this page.
      const rows = Array.isArray(lastPage.data) ? lastPage.data.length : 0;
      return rows < size ? null : lastPageParam + rows;
    },
    getPreviousPageParam: () => null,
    applyPageParam: (search, pageParam) => ({
      ...search,
      [offsetKey]: pageParam,
      [sizeKey]: search[sizeKey] ?? size,
    }),
  };
}

import {
  ARRAY_DELIMITER,
  RANGE_DELIMITER,
  SLIDER_DELIMITER,
  SORT_DELIMITER,
  SPACE_DELIMITER,
} from "@/lib/delimiters";

/**
 * The wire contract between the table and its list endpoint.
 *
 * This existed only implicitly, inside the nuqs serializer: the parameter
 * names, the delimiters, the sort encoding and the cursor convention were all
 * consequences of one client's implementation rather than anything an endpoint
 * author could read. That is fine while both halves ship together and useless
 * the moment someone else writes the server.
 *
 * Nothing here is new behaviour — it is the behaviour that was already on the
 * wire, written down, plus a validator so a response that does not honour it
 * fails loudly rather than rendering an empty table.
 */

// ── Request ─────────────────────────────────────────────────────────────────

/**
 * Reserved query parameters. Every other parameter is a column key, and its
 * value is encoded per {@link FILTER_ENCODING}.
 */
export const REQUEST_PARAMS = {
  /** Page cursor. Milliseconds since epoch for the default strategy. */
  cursor: "cursor",
  /** `"next"` (older) or `"prev"` (newer). Only sent when paging both ways. */
  direction: "direction",
  /** Page size. */
  size: "size",
  /** `"<columnKey>.<asc|desc>"` — see {@link SORT_DELIMITER}. */
  sort: "sort",
  /** Row-scoped view state. Never narrows the result set. */
  uuid: "uuid",
  /** Live-tail mode. Never narrows the result set. */
  live: "live",
} as const;

/**
 * How a filter value is written into a query parameter.
 *
 * The delimiters are shared with the client's parser; an endpoint that splits
 * differently will silently see one value where the user meant several.
 */
export const FILTER_ENCODING = {
  /** `checkbox`: `?level=error,warn` */
  array: ARRAY_DELIMITER,
  /** `slider`: `?latency=100-3000` (inclusive both ends) */
  slider: SLIDER_DELIMITER,
  /** `timerange`: `?date=1700000000000-1700003600000` (epoch ms, inclusive) */
  range: RANGE_DELIMITER,
  /** Spaces inside a single value. */
  space: SPACE_DELIMITER,
  /** `?sort=date.desc` */
  sort: SORT_DELIMITER,
} as const;

/**
 * A single value that itself contains the array delimiter cannot be encoded,
 * so `checkbox` values are required not to contain it. Stated here because it
 * is a constraint on the *data*, not on the client.
 */
export const ENCODING_CONSTRAINTS = [
  `A checkbox value may not contain ${JSON.stringify(ARRAY_DELIMITER)}.`,
  `Slider and timerange bounds may not be negative, because ${JSON.stringify(SLIDER_DELIMITER)} also separates them.`,
] as const;

// ── Response ────────────────────────────────────────────────────────────────

/** One problem with a response. `path` is a dotted location in the payload. */
export type ContractIssue = {
  path: string;
  message: string;
  /**
   * `error` — the table cannot render this correctly.
   * `warning` — renderable, but the endpoint is not doing what it claimed.
   */
  severity: "error" | "warning";
};

export type ValidateResponseOptions = {
  /**
   * What the endpoint said it computes. Fields it did not claim are not
   * required, and fields it *did* claim but omitted become warnings — that is
   * the whole point of the capability flags.
   */
  capabilities?: {
    facets?: boolean;
    totalRowCount?: boolean;
    filterRowCount?: boolean;
    chart?: boolean;
    backwardPagination?: boolean;
  };
};

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function checkFacet(
  facet: unknown,
  path: string,
  issues: ContractIssue[],
): void {
  if (!isRecord(facet)) {
    issues.push({ path, message: "facet is not an object", severity: "error" });
    return;
  }
  if (!Array.isArray(facet.rows)) {
    issues.push({
      path: `${path}.rows`,
      message: "facet is missing `rows`",
      severity: "error",
    });
  } else {
    facet.rows.forEach((row, index) => {
      if (!isRecord(row) || typeof row.total !== "number") {
        issues.push({
          path: `${path}.rows[${index}]`,
          message: "facet row must be `{ value, total: number }`",
          severity: "error",
        });
      }
    });
  }
  if (typeof facet.total !== "number") {
    issues.push({
      path: `${path}.total`,
      message: "facet is missing a numeric `total`",
      severity: "error",
    });
  }
  for (const bound of ["min", "max"] as const) {
    if (facet[bound] !== undefined && typeof facet[bound] !== "number") {
      issues.push({
        path: `${path}.${bound}`,
        message: `\`${bound}\` must be a number when present`,
        severity: "error",
      });
    }
  }
}

/**
 * Check one list response against the contract.
 *
 * Returns issues rather than throwing: a warning-only response still renders,
 * and a caller building a conformance report wants all of them at once, not
 * the first.
 */
export function validateListResponse(
  payload: unknown,
  options?: ValidateResponseOptions,
): ContractIssue[] {
  const issues: ContractIssue[] = [];
  const capabilities = options?.capabilities ?? {};

  if (!isRecord(payload)) {
    return [
      { path: "", message: "response is not an object", severity: "error" },
    ];
  }

  if (!Array.isArray(payload.data)) {
    issues.push({
      path: "data",
      message: "`data` must be an array of rows",
      severity: "error",
    });
  }

  // A cursor of `null` means "no more pages" and is the normal end state, so
  // only a wrong *type* is a problem.
  for (const key of ["nextCursor", "prevCursor"] as const) {
    const value = payload[key];
    if (
      value !== null &&
      value !== undefined &&
      typeof value !== "number" &&
      typeof value !== "string"
    ) {
      issues.push({
        path: key,
        message: `\`${key}\` must be a number, a string, or null`,
        severity: "error",
      });
    }
  }

  if (capabilities.backwardPagination && payload.prevCursor === undefined) {
    issues.push({
      path: "prevCursor",
      message:
        "endpoint declares `backwardPagination` but sent no `prevCursor` field",
      severity: "warning",
    });
  }

  if (!isRecord(payload.meta)) {
    issues.push({
      path: "meta",
      message: "`meta` must be an object",
      severity: "error",
    });
    return issues;
  }

  const meta = payload.meta;

  for (const [key, claimed] of [
    ["totalRowCount", capabilities.totalRowCount],
    ["filterRowCount", capabilities.filterRowCount],
  ] as const) {
    const value = meta[key];
    if (value === undefined) {
      if (claimed) {
        issues.push({
          path: `meta.${key}`,
          message: `endpoint declares \`${key}\` but did not send it`,
          severity: "warning",
        });
      }
    } else if (typeof value !== "number") {
      issues.push({
        path: `meta.${key}`,
        message: `\`${key}\` must be a number`,
        severity: "error",
      });
    }
  }

  if (meta.facets !== undefined) {
    if (!isRecord(meta.facets)) {
      issues.push({
        path: "meta.facets",
        message: "`facets` must be an object keyed by column",
        severity: "error",
      });
    } else {
      for (const [key, facet] of Object.entries(meta.facets)) {
        checkFacet(facet, `meta.facets.${key}`, issues);
      }
    }
  } else if (capabilities.facets) {
    issues.push({
      path: "meta.facets",
      message: "endpoint declares `facets` but did not send them",
      severity: "warning",
    });
  }

  if (meta.chartData !== undefined) {
    if (!Array.isArray(meta.chartData)) {
      issues.push({
        path: "meta.chartData",
        message: "`chartData` must be an array",
        severity: "error",
      });
    } else {
      meta.chartData.forEach((point, index) => {
        if (!isRecord(point) || typeof point.timestamp !== "number") {
          issues.push({
            path: `meta.chartData[${index}]`,
            message: "each point must carry a numeric `timestamp`",
            severity: "error",
          });
        }
      });
    }
  } else if (capabilities.chart) {
    issues.push({
      path: "meta.chartData",
      message: "endpoint declares `chart` but did not send `chartData`",
      severity: "warning",
    });
  }

  if (meta.actions !== undefined && !Array.isArray(meta.actions)) {
    issues.push({
      path: "meta.actions",
      message: "`actions` must be an array of descriptors",
      severity: "error",
    });
  }

  return issues;
}

/** True when nothing in the response prevents the table from rendering it. */
export function isContractValid(issues: readonly ContractIssue[]): boolean {
  return !issues.some((issue) => issue.severity === "error");
}

import {
  isContractValid,
  validateListResponse,
  type ContractIssue,
} from "./contract";

/**
 * A conformance kit for a list endpoint.
 *
 * The filter-semantics corpus in `lib/filters/testing/conformance.ts` answers
 * "does this engine interpret a filter the way the table does". This answers
 * the other half: "does this endpoint speak the HTTP contract" — the parameters
 * it must read, the shape it must return, and whether its manifest tells the
 * truth about itself.
 *
 * It is deliberately a plain async function with no test-framework dependency,
 * so it ships to consumers and can run in their test runner, in CI against a
 * deployed URL, or from a script. That is also why it does not live under
 * `testing/` — the registry does not ship anything from there, and this is a
 * runtime verifier rather than test scaffolding.
 *
 * ## What it cannot check
 *
 * Filter *semantics* — whether `?level=error,warn` returns the right rows —
 * belong to the filter corpus, which needs known data. This kit runs against a
 * live endpoint whose contents it does not know, so it checks structure,
 * self-consistency, and the claims the manifest makes.
 */

/**
 * The part of a `TableManifest` this kit reads.
 *
 * Structural rather than an import of `TableManifest`: the conformance kit
 * ships with the query block, which does not depend on the schema block, and a
 * real manifest satisfies this shape anyway. Keeping it structural is also what
 * lets someone conformance-test an endpoint whose manifest they hand-wrote.
 */
export type ConformanceManifest = {
  primaryKey: string;
  capabilities: {
    facets?: boolean;
    facetedColumns?: readonly string[];
    totalRowCount?: boolean;
    filterRowCount?: boolean;
    chart?: boolean;
    backwardPagination?: boolean;
  };
  schema: {
    columns: readonly { key: string; filter?: { type?: string } | null }[];
  };
};

export type ConformanceCheck = {
  id: string;
  description: string;
  status: "pass" | "fail" | "skip";
  /** Why it failed, or why it was skipped. */
  detail?: string;
  issues?: ContractIssue[];
};

export type ConformanceReport = {
  checks: ConformanceCheck[];
  passed: number;
  failed: number;
  skipped: number;
  ok: boolean;
};

export type EndpointConformanceOptions = {
  /** The list endpoint, without a query string. */
  url: string;
  /** The manifest this endpoint serves. Its capabilities are what we hold it to. */
  manifest: ConformanceManifest;
  /** Defaults to global `fetch`. Supply one to add auth headers. */
  fetch?: typeof fetch;
  /** Parses a response body. Defaults to `response.json()`. */
  parse?: (response: Response) => Promise<unknown>;
  /** Page size to request. Defaults to 5, to keep the probe cheap. */
  size?: number;
};

function record(
  checks: ConformanceCheck[],
  check: ConformanceCheck,
): ConformanceCheck {
  checks.push(check);
  return check;
}

function pass(id: string, description: string): ConformanceCheck {
  return { id, description, status: "pass" };
}

function fail(
  id: string,
  description: string,
  detail: string,
  issues?: ContractIssue[],
): ConformanceCheck {
  return {
    id,
    description,
    status: "fail",
    detail,
    ...(issues ? { issues } : {}),
  };
}

function skip(
  id: string,
  description: string,
  detail: string,
): ConformanceCheck {
  return { id, description, status: "skip", detail };
}

function join(url: string, query: string): string {
  if (!query) return url;
  return `${url}${url.includes("?") ? "&" : "?"}${query}`;
}

/**
 * Run every check against a live endpoint.
 *
 * Never throws for a failing endpoint — a thrown request is itself a recorded
 * failure, so one unreachable URL does not hide the other results.
 */
export async function runEndpointConformance(
  options: EndpointConformanceOptions,
): Promise<ConformanceReport> {
  const doFetch = options.fetch ?? fetch;
  const parse = options.parse ?? ((response: Response) => response.json());
  const size = options.size ?? 5;
  const { manifest, url } = options;
  const checks: ConformanceCheck[] = [];

  const get = async (
    query: string,
  ): Promise<{ payload?: unknown; error?: string }> => {
    try {
      const response = await doFetch(join(url, query));
      if (!response.ok) {
        return { error: `${response.status} ${response.statusText}`.trim() };
      }
      return { payload: await parse(response) };
    } catch (cause) {
      return { error: cause instanceof Error ? cause.message : String(cause) };
    }
  };

  // ── 1. The endpoint answers at all, in the right shape ───────────────────

  const base = await get(`size=${size}`);
  if (base.error || base.payload === undefined) {
    record(
      checks,
      fail(
        "responds",
        "returns a 2xx for an unfiltered request",
        base.error ?? "no body",
      ),
    );
    return summarize(checks);
  }
  record(checks, pass("responds", "returns a 2xx for an unfiltered request"));

  const baseIssues = validateListResponse(base.payload, {
    capabilities: manifest.capabilities,
  });
  record(
    checks,
    isContractValid(baseIssues)
      ? {
          id: "response-shape",
          description: "response matches the list contract",
          status: "pass",
          ...(baseIssues.length > 0 ? { issues: baseIssues } : {}),
        }
      : fail(
          "response-shape",
          "response matches the list contract",
          `${baseIssues.filter((i) => i.severity === "error").length} contract error(s)`,
          baseIssues,
        ),
  );

  const first = base.payload as {
    data?: unknown[];
    nextCursor?: unknown;
    meta?: Record<string, unknown>;
  };

  // ── 2. `size` is honoured ────────────────────────────────────────────────

  if (Array.isArray(first.data)) {
    record(
      checks,
      first.data.length <= size
        ? pass("size", "honours the `size` parameter")
        : fail(
            "size",
            "honours the `size` parameter",
            `asked for ${size}, received ${first.data.length}`,
          ),
    );
  }

  // ── 3. Rows carry the primary key ────────────────────────────────────────

  if (Array.isArray(first.data) && first.data.length > 0) {
    const missing = first.data.filter((row) => {
      if (typeof row !== "object" || row === null) return true;
      return readPath(row, manifest.primaryKey) === undefined;
    });
    record(
      checks,
      missing.length === 0
        ? pass("primary-key", "every row carries the manifest's `primaryKey`")
        : fail(
            "primary-key",
            "every row carries the manifest's `primaryKey`",
            `${missing.length} of ${first.data.length} rows have no ${JSON.stringify(manifest.primaryKey)}`,
          ),
    );

    const ids = first.data.map((row) =>
      String(readPath(row as object, manifest.primaryKey)),
    );
    record(
      checks,
      new Set(ids).size === ids.length
        ? pass("primary-key-unique", "primary keys are unique within a page")
        : fail(
            "primary-key-unique",
            "primary keys are unique within a page",
            "the same id appeared twice, so row identity is not stable",
          ),
    );
  } else {
    record(
      checks,
      skip(
        "primary-key",
        "every row carries the manifest's `primaryKey`",
        "the endpoint returned no rows",
      ),
    );
  }

  // ── 4. Declared facets are actually computed ─────────────────────────────

  if (manifest.capabilities.facets) {
    const facets = (first.meta?.facets ?? {}) as Record<string, unknown>;
    const expected =
      manifest.capabilities.facetedColumns ??
      manifest.schema.columns
        // Only `checkbox` and `slider` need a facet: one wants the set of
        // values, the other wants bounds. An `input` filter is free text and a
        // `timerange` carries its own bounds, so neither has anything to group.
        // "Has a filter descriptor" is the wrong test — a plain `col.string()`
        // gets an `input` filter by default and would be demanded here.
        .filter(
          (column) =>
            column.filter?.type === "checkbox" ||
            column.filter?.type === "slider",
        )
        .map((column) => column.key);
    const absent = expected.filter((key) => !(key in facets));
    record(
      checks,
      absent.length === 0
        ? pass("facets", "computes a facet for every column it claims")
        : fail(
            "facets",
            "computes a facet for every column it claims",
            `no facet for: ${absent.join(", ")}`,
          ),
    );
  } else {
    record(
      checks,
      skip(
        "facets",
        "computes a facet for every column it claims",
        "the manifest does not declare `facets`",
      ),
    );
  }

  // ── 5. Paging forwards advances ──────────────────────────────────────────

  if (first.nextCursor === null || first.nextCursor === undefined) {
    record(
      checks,
      skip(
        "paging",
        "a second page returns different rows",
        "the first page was the last page",
      ),
    );
  } else {
    const second = await get(
      `size=${size}&cursor=${encodeURIComponent(String(first.nextCursor))}&direction=next`,
    );
    if (second.error || second.payload === undefined) {
      record(
        checks,
        fail(
          "paging",
          "a second page returns different rows",
          second.error ?? "no body",
        ),
      );
    } else {
      const secondIssues = validateListResponse(second.payload, {
        capabilities: manifest.capabilities,
      });
      const nextData = (second.payload as { data?: unknown[] }).data ?? [];
      const firstIds = new Set(
        (first.data ?? []).map((row) =>
          String(readPath(row as object, manifest.primaryKey)),
        ),
      );
      const overlap = nextData.filter((row) =>
        firstIds.has(String(readPath(row as object, manifest.primaryKey))),
      );

      if (!isContractValid(secondIssues)) {
        record(
          checks,
          fail(
            "paging",
            "a second page returns different rows",
            "the second page does not match the contract",
            secondIssues,
          ),
        );
      } else if (nextData.length > 0 && overlap.length === nextData.length) {
        // Every row repeated: the cursor was ignored, which is an infinite
        // scroll that never advances.
        record(
          checks,
          fail(
            "paging",
            "a second page returns different rows",
            "the second page repeated the first page exactly — is `cursor` being read?",
          ),
        );
      } else {
        record(checks, pass("paging", "a second page returns different rows"));
      }
    }
  }

  // ── 6. Backwards paging, when claimed ────────────────────────────────────

  if (!manifest.capabilities.backwardPagination) {
    record(
      checks,
      skip(
        "backward-paging",
        "accepts `direction=prev`",
        "the manifest does not declare `backwardPagination`",
      ),
    );
  } else {
    const prevCursor = (base.payload as { prevCursor?: unknown }).prevCursor;
    if (prevCursor === null || prevCursor === undefined) {
      record(
        checks,
        skip(
          "backward-paging",
          "accepts `direction=prev`",
          "no `prevCursor` to page back from",
        ),
      );
    } else {
      const back = await get(
        `size=${size}&cursor=${encodeURIComponent(String(prevCursor))}&direction=prev`,
      );
      record(
        checks,
        back.error
          ? fail("backward-paging", "accepts `direction=prev`", back.error)
          : isContractValid(
                validateListResponse(back.payload, {
                  capabilities: manifest.capabilities,
                }),
              )
            ? pass("backward-paging", "accepts `direction=prev`")
            : fail(
                "backward-paging",
                "accepts `direction=prev`",
                "the response does not match the contract",
              ),
      );
    }
  }

  // ── 7. An unknown parameter does not break the endpoint ──────────────────

  const noisy = await get(`size=${size}&__dtf_unknown_param=1`);
  record(
    checks,
    noisy.error
      ? fail(
          "unknown-param",
          "ignores an unrecognised query parameter",
          `an unknown parameter produced ${noisy.error} — the table adds view-state params that never narrow results`,
        )
      : pass("unknown-param", "ignores an unrecognised query parameter"),
  );

  return summarize(checks);
}

/** Reads a possibly-dotted key path off a row. */
function readPath(row: unknown, path: string): unknown {
  if (row === null || typeof row !== "object") return undefined;
  if (!path.includes(".")) return (row as Record<string, unknown>)[path];
  let current: unknown = row;
  for (const segment of path.split(".")) {
    if (current === null || typeof current !== "object") return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

function summarize(checks: ConformanceCheck[]): ConformanceReport {
  const passed = checks.filter((check) => check.status === "pass").length;
  const failed = checks.filter((check) => check.status === "fail").length;
  const skipped = checks.filter((check) => check.status === "skip").length;
  return { checks, passed, failed, skipped, ok: failed === 0 };
}

/** A one-line-per-check summary, for a CI log. */
export function formatConformanceReport(report: ConformanceReport): string {
  const symbol = { pass: "PASS", fail: "FAIL", skip: "SKIP" } as const;
  const lines = report.checks.map((check) => {
    const head = `${symbol[check.status]}  ${check.id}: ${check.description}`;
    return check.detail ? `${head}\n      ${check.detail}` : head;
  });
  lines.push(
    `\n${report.passed} passed, ${report.failed} failed, ${report.skipped} skipped`,
  );
  return lines.join("\n");
}
